Let $\hat{\mathrm{n}}$ be the unit vector perpendicular to $\overline{\mathrm{b}}$ and $\bar{c}$.
$\begin{aligned}
{\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right] } & =\overline{\mathrm{a}} \cdot(\overline{\mathrm{~b}} \times \overline{\mathrm{c}}) \\
& =\overline{\mathrm{a}} \cdot(|\overline{\mathrm{~b}}||\bar{c}| \sin \theta \hat{\mathrm{n}}) \\
& =\overline{\mathrm{a}} \cdot\left(3 \times 4 \sin \frac{\pi}{3} \cdot \hat{\mathrm{n}}\right) \\
& =\overline{\mathrm{a}} \cdot\left(12 \times \frac{\sqrt{3}}{2} \hat{\mathrm{n}}\right) \\
& =6 \sqrt{3}|\overrightarrow{\mathrm{a}}| \hat{\mathrm{n}} \mid \cos 0 \\
& =6 \sqrt{3} \times 2 \times 1 \\
& =12 \sqrt{3}
\end{aligned}$

$\begin{aligned}
& 3 \overline{\mathrm{a}}+\overline{\mathrm{b}}-2 \overline{\mathrm{c}} \\
& =3(2 \hat{\mathrm{i}}-\hat{\mathrm{j}}+\hat{\mathrm{k}})+(\hat{\mathrm{i}}+\hat{\mathrm{j}}-2 \hat{\mathrm{k}})-2(4 \hat{\mathrm{i}}-2 \hat{\mathrm{j}}+\hat{\mathrm{k}}) \\
& =-(\hat{\mathrm{i}}+2 \hat{\mathrm{j}}-\hat{\mathrm{k}}
\end{aligned}\therefore \quad$ The unit vector in the direction of $3 \overline{\mathrm{a}}+\overline{\mathrm{b}}-2 \overline{\mathrm{c}}$ is
$\begin{aligned}
& \frac{-\hat{\mathrm{i}}+2 \hat{\mathrm{j}}-\hat{\mathrm{k}}}{|\hat{-\mathrm{i}}+2 \hat{\mathrm{j}}-\hat{\mathrm{k}}|} \\
& =\frac{-\hat{\mathrm{i}}+2 \hat{\mathrm{j}}-\hat{\mathrm{k}}}{\sqrt{(-1)^2+2^2+(-1)^2}} \\
& =\frac{1}{\sqrt{6}}(-\hat{\mathrm{i}}+2 \hat{\mathrm{j}}-\hat{\mathrm{k}})
\end{aligned}$

$\overline{\mathrm{a}}, \overline{\mathrm{b}}, \overline{\mathrm{c}}$ are coplanar vectors.
$\Rightarrow\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right]=0$
Let $\bar{\alpha}=2 \overline{\mathrm{a}}-\overline{\mathrm{b}}, \bar{\beta}=2 \overline{\mathrm{~b}}-\overline{\mathrm{c}}$ and $\gamma=2 \overline{\mathrm{c}}-\overline{\mathrm{a}}$. Then,
$\begin{aligned}
& {\left[\begin{array}{ccc}
\bar{\alpha} & \bar{\beta} & \bar{\gamma}
\end{array}\right]=\left|\begin{array}{ccc}
2 & -1 & 0 \\
0 & 2 & -1 \\
-1 & 0 & 2
\end{array}\right|\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right]} \\
& \Rightarrow\left[\begin{array}{lll}
\bar{\alpha} & \bar{\beta} & \bar{\gamma}
\end{array}\right]=7\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right]=7(0)=0
\end{aligned}$

Here, $\hat{a} \cdot \hat{b}=0\therefore \quad \hat{a}$ and $\hat{b}$ are perpendicular unit vectors.
Now, $(2 \hat{a}-\hat{b}) \cdot\{(\hat{a} \times \hat{b}) \times(\hat{a}+2 \hat{b})\}=\left[\begin{array}{lll}
2 \hat{a}-\hat{b} & \hat{a} \times \hat{b} & \hat{a}+2 \hat{b}
\end{array}\right]\begin{aligned} & =-[\hat{a} \times \hat{b} \quad 2 \hat{a}-\hat{b} \quad \hat{a}+2 \hat{b}] \\ & =-(\hat{a} \times \hat{b}) \cdot\{(2 \hat{a}-\hat{b}) \times(\hat{a}+2 \hat{b})\} \\ & =-(\hat{a} \times \hat{b}) \cdot 5(\hat{a} \times \hat{b}) \\ & =-5|\hat{a} \times \hat{b}|=-5|\hat{a}|^2|\hat{b}|^2 \\ & =-5\end{aligned}\begin{aligned} & \ldots[\because \hat{a} \perp \hat{b}] \\ & \ldots[\because|\hat{a}|=|\hat{b}|=1]\end{aligned}$

$\begin{aligned}
M & =|\overrightarrow{O P}| \\
M & =\hat{a} \cos t+\hat{b} \sin t \\
& =\sqrt{(\hat{a} \cos t)^2+(\hat{b} \sin t)^2+2(\hat{a} \cos t) \cdot(\hat{b} \cdot \sin t)} \\
& =\sqrt{\sin ^2 t+\cos ^2 t+\hat{a} \cdot \hat{b}(2 \sin t \cos t)} \\
& =\sqrt{1+\hat{a} \cdot \hat{b}(\sin 2 t)}
\end{aligned}$<br/>Maximum value of $\sin 2 t=1\begin{array}{ll}
\therefore & 2 t=\sin ^{-1}(1) \\
\therefore & t=\frac{\pi}{4}
\end{array}
$\therefore \quad M=\sqrt{1+\hat{a} \cdot \hat{b}(1)}=(1+\hat{a} \cdot \hat{b})^{\frac{1}{2}}$ \\ Now, $\hat{\mathrm{u}}=\frac{\overline{\mathrm{OP}}}{|\overrightarrow{\mathrm{OP}}|}=\frac{\hat{a} \cos t+\hat{b} \sin t}{|\hat{a} \sin t+\hat{b} \sin t|}=\frac{\hat{a}\left(\frac{1}{\sqrt{2}}\right)+\hat{b}\left(\frac{1}{\sqrt{2}}\right)}{\left|\hat{a}\left(\frac{1}{\sqrt{2}}\right)+\hat{b}\left(\frac{1}{\sqrt{2}}\right)\right|}$ \\ Unit vector of OP is
$\hat{u}=\frac{\hat{a}+\hat{b}}{|(\hat{a}+\hat{b})|}

Let the required vector be $\overline{\mathrm{r}}=x \hat{\mathrm{i}}+y \hat{\mathrm{j}}+z \hat{\mathrm{k}}$.
Then, $|\hat{r}|=6\Rightarrow x^2+y^2+z^2=36$<br/>Now, $\bar{r}$ is perpendicular to vectors $\bar{a}=2 \hat{i}+\hat{j}-3 \hat{k}$ and $\bar{b}=\hat{i}-2 \hat{j}+\hat{k}$.
$\begin{array}{ll}
\therefore & \overline{\mathrm{a}} \times \overline{\mathrm{b}}=\left|\begin{array}{ccc}
\hat{\mathrm{i}} & \hat{\mathrm{j}} & \hat{\mathrm{k}} \\
2 & 1 & -3 \\
1 & -2 & 1
\end{array}\right|=-5(\hat{\mathrm{i}}+\hat{\mathrm{j}}+\hat{\mathrm{k}}) \\
\therefore & x=y=\mathrm{z} \\
\therefore & \text { Let } x=y=\mathrm{z}=\lambda
\end{array}
Let $x=y=z=\lambda$.
From (i), we get
$\begin{array}{ll} 
& 3 \lambda^2=36 \\
\therefore \quad & \lambda=2 \sqrt{3}
\end{array}
$\therefore \quad$ Required vector is $2 \sqrt{3}(\hat{\mathrm{i}}+\hat{\mathrm{j}}+\hat{\mathrm{k}})$

$\begin{aligned}
& \overline{\mathrm{a}}-\overline{\mathrm{b}}+3 \overline{\mathrm{c}} \\
= & (2-4+3) \hat{\mathrm{i}}+(2+2-6) \hat{\mathrm{j}}+(2-3+3) \hat{\mathrm{k}} \\
= & \hat{\mathrm{i}}-2 \hat{\mathrm{j}}+2 \hat{\mathrm{k}}
\end{aligned}\therefore \quad$ Required vector is the multiple of the above vector and has magnitude 6 units.
Option (A) satisfies this condition.

$\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right]=\left|\begin{array}{ccc}
1 & 0 & -1 \\
x & 1 & 1-x \\
y & x & 1+x-y
\end{array}\right|$<br/>Applying $\mathrm{C}_3 \Rightarrow \mathrm{C}_3+\mathrm{C}_1$, we get
$[\overline{\mathrm{a}} \overline{\mathrm{~b}} \overline{\mathrm{c}}]=\left|\begin{array}{ccc}
1 & 0 & 0 \\
x & 1 & 1 \\
y & x & 1+x
\end{array}\right|=1(1+x-x)=1$

Given, $|\vec{a}|=1,|\bar{b}|=1$ and $|\bar{c}|=2\begin{aligned}
& \text { Also, } \overline{\mathrm{a}} \times(\overline{\mathrm{a}} \times \overline{\mathrm{c}})+\overline{\mathrm{b}}=\overline{0} \\
& \Rightarrow(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}}-(\overline{\mathrm{a}} \cdot \overline{\mathrm{a}}) \overline{\mathrm{c}}+\overline{\mathrm{b}}=\overline{0} \\
& \Rightarrow(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}}-\overline{\mathrm{c}}+\overline{\mathrm{b}}=\overline{0} \quad \ldots\left[\because \overline{\mathrm{a}} \cdot \overline{\mathrm{a}}=|\overline{\mathrm{a}}|^2=1\right] \\
& \Rightarrow(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}}-\overline{\mathrm{c}}=-\overline{\mathrm{b}}
\end{aligned}\begin{aligned} & \Rightarrow|(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}}-\overline{\mathrm{c}}|=|-\overline{\mathrm{b}}| \\ & \Rightarrow|(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}}-\overline{\mathrm{c}}|^2=|\overline{\mathrm{b}}|^2 \\ & \Rightarrow|(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}}|^2+|\overline{\mathrm{c}}|^2-2\{(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{a}} \cdot \overline{\mathrm{c}}\}=|\overline{\mathrm{b}}|^2 \\ & \Rightarrow(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}})^2|\overline{\mathrm{a}}|^2+|\overline{\mathrm{c}}|^2-2(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}})(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}})=|\overline{\mathrm{b}}|^2 \\ & \Rightarrow(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}})^2\left\{|\overline{\mathrm{a}}|^2-2\right\}+|\overline{\mathrm{c}}|^2=|\overline{\mathrm{b}}|^2\end{aligned}\begin{aligned}
& \Rightarrow-(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}})^2+4=1 \quad \ldots\left[\because|\overline{\mathrm{~b}}|^2=1,|\overline{\mathrm{c}}|^2=4\right] \\
& \Rightarrow(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}})^2=3 \\
& \Rightarrow \overline{\mathrm{a}} \cdot \overline{\mathrm{c}}= \pm \sqrt{3} \\
& \Rightarrow|\overline{\mathrm{a}}||\overline{\mathrm{c}}| \cos \theta=\sqrt{3}
\end{aligned}$
where $\theta$ is an acute angle between $\overline{\mathrm{a}}$ and $\overline{\mathrm{c}}\Rightarrow \cos \theta=\frac{\sqrt{3}}{2} \Rightarrow \theta=\frac{\pi}{6}$

Let $\overline{\mathrm{a}}=\hat{\mathrm{i}}+\hat{\mathrm{j}}-\hat{\mathrm{k}}, \overline{\mathrm{b}}=\hat{\mathrm{i}}+\hat{\mathrm{j}}+\hat{\mathrm{k}}, \overline{\mathrm{c}}=2 \hat{\mathrm{i}}+\hat{\mathrm{j}}+\hat{\mathrm{k}}$.
Then, required unit vectors are given by
$\bar{\alpha}= \pm \frac{\overline{\mathrm{a}} \times(\overline{\mathrm{b}} \times \overline{\mathrm{c}}) \cdot}{|\overline{\mathrm{a}} \times(\overline{\mathrm{b}} \times \overline{\mathrm{c}})|}$<br/>Now, $\overline{\mathrm{a}} \times(\overline{\mathrm{b}} \times \overrightarrow{\mathrm{c}})=(\overline{\mathrm{a}} \cdot \overline{\mathrm{c}}) \overline{\mathrm{b}}-(\overline{\mathrm{a}} \cdot \overline{\mathrm{b}}) \overline{\mathrm{c}}\begin{array}{ll}
\therefore & =2(\hat{i}+\hat{j}+\hat{k})-1(2 \hat{i}+\hat{j}+\hat{k})=\hat{j}+\hat{k} \\
\therefore & |\bar{a} \times(\bar{b} \times \bar{c})|=\sqrt{1+1}=\sqrt{2}
\end{array}
Hence, required unit vectors are
$\bar{\alpha}= \pm \frac{\hat{\mathrm{j}}+\hat{\mathrm{k}}}{\sqrt{2}}

$\begin{aligned}
\overline{\mathrm{a}} \times \overline{\mathrm{b}} & =\left|\begin{array}{ccc}
\hat{\mathrm{i}} & \hat{\mathrm{j}} & \hat{\mathrm{k}} \\
3 & -\alpha & 1 \\
1 & \alpha & 3
\end{array}\right| \\
& =-4 \alpha \hat{\mathrm{i}}-8 \hat{\mathrm{j}}+4 \alpha \hat{\mathrm{k}}
\end{aligned}$<br/>Area of parallelogram $=|\overline{\mathrm{a}} \times \overline{\mathrm{b}}|\begin{aligned}
& \Rightarrow 8 \sqrt{3}=\sqrt{16 \alpha^2+64+16 \alpha^2} \\
& \Rightarrow 8 \sqrt{3}=\sqrt{32 \alpha^2+64}
\end{aligned}$<br/>Squaring on both sides, we get
$\begin{aligned}
& 192=32 \alpha^2+64 \\
& \Rightarrow 32 \alpha^2=128 \\
& \Rightarrow \alpha^2=4 \\
& \begin{aligned}
& \overline{\mathrm{a}} \cdot \overline{\mathrm{~b}}=(3 \hat{\mathrm{i}}-\alpha \hat{\mathrm{j}}+\hat{\mathrm{k}}) \cdot(\hat{\mathrm{i}}+\alpha \hat{\mathrm{j}}+3 \hat{\mathrm{k}}) \\
& \quad=3-\alpha^2+3 \\
& \quad=6-4 \\
& \quad=2
\end{aligned}
\end{aligned}$

Given, $\overline{\mathrm{a}}=\hat{\mathrm{i}}+\hat{\mathrm{j}}+\hat{\mathrm{k}}$ and $\overline{\mathrm{a}} \times \overline{\mathrm{b}}=\hat{\mathrm{j}}-\hat{\mathrm{k}}\overline{\mathrm{a}} \cdot \overline{\mathrm{~b}}=1$<br/>Let $\overline{\mathrm{b}}=x \hat{\mathrm{i}}+y \hat{\mathrm{j}}+z \hat{\mathrm{k}}\begin{aligned}
& \overline{\mathrm{a}} \times \overline{\mathrm{b}}=\left|\begin{array}{ccc}
\hat{\mathrm{i}} & \hat{\mathrm{j}} & \hat{\mathrm{k}} \\
1 & 1 & 1 \\
x & y & \mathrm{z}
\end{array}\right| \\
& \Rightarrow \hat{\mathrm{j}}-\hat{\mathrm{k}}=(\mathrm{z}-y) \hat{\mathrm{i}}-\hat{\mathrm{j}}(\mathrm{z}-x)+\hat{\mathrm{k}}(y-x) \\
& \Rightarrow \mathrm{z}-y=0 ...(i)\\
& \mathrm{z}-x=-1...(ii)
\end{aligned}\begin{array}{ll} 
& y-x=-1 ...(iii)\\
\therefore \quad & \text { Also, } \overline{\mathrm{a}} \cdot \overline{\mathrm{~b}}=1 \\
\therefore \quad & x+y+\mathrm{z}=1
...(iv)\end{array} \\ Solving (i), (ii), (iii) and (iv), we get
$\begin{aligned}
& x=1, y=0, \mathrm{z}=0 \\
\therefore \quad & \overline{\mathrm{~b}}=\hat{\mathrm{i}}
\end{aligned}

$\begin{aligned}
& \text { Given, } 2 \overline{\mathrm{a}}+\overline{\mathrm{b}}=4 \hat{\mathrm{i}}-\hat{\mathrm{j}}+5 \hat{\mathrm{k}} \\
& \overline{\mathrm{a}}+2 \overline{\mathrm{~b}}=5 \hat{\mathrm{i}}+4 \hat{\mathrm{j}}+\hat{\mathrm{k}} \\
& |2 \overline{\mathrm{a}}+\overline{\mathrm{b}}|=\sqrt{(4)^2+(-1)^2+(5)^2}=\sqrt{42} \\
& |\overline{\mathrm{a}}+2 \overline{\mathrm{~b}}|=\sqrt{5^2+4^2+1^2}=\sqrt{42}
\end{aligned}\therefore \quad$ Angle between $(2 \bar{a}+\bar{b})$ and $(\bar{a}+2 \bar{b})$ is given by
$\begin{aligned}
\cos \theta & =\frac{(2 \bar{a}+\bar{b})(\bar{a}+2 \bar{b})}{|2 \bar{a}+\bar{b}||\bar{a}+2 \bar{b}|} \\
& =\frac{(4 \hat{i}-\hat{j}+5 \hat{k})(5 \hat{i}+4 \hat{j}+\hat{k})}{\sqrt{42} \cdot \sqrt{42}}=\frac{21}{42} \\
\cos \theta & =\frac{1}{2} \\
\Rightarrow \theta & =\frac{\pi}{3}
\end{aligned}$

$\begin{array}{ll} & \bar{a}=2 \hat{i}+\hat{j}-2 \hat{k} \\ & \bar{b}=\hat{i}+\hat{j} \\ & |\bar{a}|=\sqrt{4+1+4}=3 \\ & \bar{a} \times \bar{b}=\left|\begin{array}{ccc}\hat{i} & \hat{j} & \hat{k} \\ 2 & 1 & -2 \\ 1 & 1 & 0\end{array}\right|=2 \hat{i}-2 \hat{j}+\hat{k} \\ \therefore \quad & |\bar{a} \times \bar{b}|=\sqrt{4+4+1}=3\end{array}
Angle between $\overline{\mathrm{c}}$ and $\overline{\mathrm{a}} \times \overline{\mathrm{b}}=30^{\circ}$
...[Given]
$\sin 30^{\circ}=\frac{|(\overline{\mathrm{a}} \times \overline{\mathrm{b}}) \times \overline{\mathrm{c}}|}{|\overline{\mathrm{a}} \times \overline{\mathrm{b}}||\overline{\mathrm{c}}|}\begin{aligned}
& \frac{1}{2}=\frac{3}{3 \times|\overline{\mathrm{c}}|} \\
& \Rightarrow|\overline{\mathrm{c}}|=2
\end{aligned}\begin{aligned}
& \text { Now, }|\overline{\mathrm{c}}-\overline{\mathrm{a}}|=3 \\
& \Rightarrow|\overline{\mathrm{c}}|^2+|\overline{\mathrm{a}}|^2-2 \overline{\mathrm{a}} \cdot \overline{\mathrm{c}}=9 \\
& \Rightarrow 4+9-2 \overline{\mathrm{a}} \cdot \overline{\mathrm{c}}=9 \\
& \Rightarrow \overline{\mathrm{a}} \cdot \overline{\mathrm{c}}=2
\end{aligned}

$\begin{aligned}
& {\left[\begin{array}{lll}
\overline{\mathrm{m}} \overline{\mathrm{a}}+\overline{\mathrm{b}} & \mathrm{~m} \overline{\mathrm{~b}}+\overline{\mathrm{c}} & \mathrm{~m} \overline{\mathrm{c}}+\overline{\mathrm{a}}
\end{array}\right]=28\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right]} \\
& \Rightarrow(\mathrm{ma}+\overline{\mathrm{b}})[(\mathrm{m} \overline{\mathrm{~b}}+\overline{\mathrm{c}}) \times(\mathrm{m} \overline{\mathrm{c}}+\overline{\mathrm{a}})]=28\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right] \\
& \Rightarrow(m \bar{a}+\bar{b}) \\
& {\left[\mathrm{m}^2(\overline{\mathrm{~b}} \times \overline{\mathrm{c}})+\mathrm{m}(\overline{\mathrm{~b}} \times \overline{\mathrm{a}})+\mathrm{m}(\overline{\mathrm{c}} \times \overline{\mathrm{c}})+(\overline{\mathrm{c}} \times \overline{\mathrm{a}})\right]} \\
& =28\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right]
\end{aligned}\begin{aligned}
& \Rightarrow(\mathrm{ma}+\overline{\mathrm{b}})\left[\mathrm{m}^2(\overline{\mathrm{~b}} \times \overline{\mathrm{c}})+\mathrm{m}(\overline{\mathrm{~b}} \times \overline{\mathrm{a}})+(\overline{\mathrm{c}} \times \overline{\mathrm{a}})\right] \\
& =28\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right] \\
& \Rightarrow m \bar{a} \cdot m^2(\overline{\mathrm{~b}} \times \overline{\mathrm{c}})+\mathrm{m}^2 \overline{\mathrm{a}}(\overline{\mathrm{~b}} \times \overline{\mathrm{a}})+\mathrm{ma}(\overline{\mathrm{c}} \times \overline{\mathrm{a}}) \\
& +\overline{\mathrm{b}} \cdot \mathrm{~m}^2(\overline{\mathrm{~b}} \times \overline{\mathrm{c}})+\overline{\mathrm{b}} \cdot \mathrm{~m}(\overline{\mathrm{~b}} \times \overline{\mathrm{a}})+\overline{\mathrm{b}} \cdot(\overline{\mathrm{c}} \times \overline{\mathrm{a}}) \\
& =28\left[\begin{array}{lll}
\overline{\mathrm{a}} & \overline{\mathrm{~b}} & \overline{\mathrm{c}}
\end{array}\right] .
\end{aligned}\begin{aligned} & \Rightarrow \mathrm{m}^3\left[\begin{array}{lll}\overline{\mathrm{a}} & \overline{\mathrm{b}} & \overline{\mathrm{c}}\end{array}\right]+\left[\begin{array}{lll}\overline{\mathrm{b}} & \overline{\mathrm{a}} & \overline{\mathrm{c}}\end{array}\right]=28\left[\begin{array}{lll}\overline{\mathrm{a}} & \overline{\mathrm{b}} & \overline{\mathrm{c}}\end{array}\right] \\ & \Rightarrow \mathrm{m}^3+1=28 \\ & \Rightarrow \mathrm{~m}^3=27 \\ & \Rightarrow \mathrm{~m}=3\end{aligned}$

Lines $\mathrm{L}_1$ and $\mathrm{L}_2$ are parallel to the vectors
$\begin{aligned}
& \overline{\mathrm{b}}_1=3 \hat{\mathrm{i}}+2 \hat{\mathrm{j}}+\hat{\mathrm{k}} \\
& \overline{\mathrm{~b}}_2=2 \hat{\mathrm{i}}+\hat{\mathrm{j}}+3 \hat{\mathrm{k}} \text { respectively. }
\end{aligned}\therefore \quad$ The unit vector perpendicular to both $\mathrm{L}_1$ and $\mathrm{L}_2$ is $\hat{n}=\frac{\bar{b}_1 \times \bar{b}_2}{\left|\bar{b}_1 \times \bar{b}_2\right|}$
Now, $\begin{aligned} \overline{\mathrm{b}}_1 \times \overline{\mathrm{b}}_2 & =\left|\begin{array}{lll}\hat{\mathrm{i}} & \hat{\mathrm{j}} & \hat{\mathrm{k}} \\ 3 & 2 & 1 \\ 2 & 1 & 3\end{array}\right| \\ & =5 \hat{\mathrm{i}}-7 \hat{\mathrm{j}}-\hat{\mathrm{k}}\end{aligned}\therefore \quad \hat{\mathrm{n}}=\frac{5 \hat{\mathrm{i}}-7 \hat{\mathrm{j}}-\hat{\mathrm{k}}}{5 \sqrt{3}}$

Let $A D$ be the median of $\triangle A B C$.
$\begin{aligned}
\overline{\mathrm{AD}} & =\frac{\overline{\mathrm{AB}}+\overline{\mathrm{AC}}}{2} \\
& =\frac{8 \hat{\mathrm{i}}-2 \hat{\mathrm{j}}+8 \hat{\mathrm{k}}}{2} \\
& =4 \hat{\mathrm{i}}-\hat{\mathrm{j}}+4 \hat{\mathrm{k}}
\end{aligned}\therefore|\overline{\mathrm{AD}}|=\sqrt{4^2+1^2+4^2}=\sqrt{33}$ units

$|\vec{a}|=\sqrt{27},|\vec{b}|=7 \text { and }|\vec{a} \times \bar{b}|=35$<br/>We know that
$\begin{array}{rlrl} 
& |\overline{\mathrm{a}} \times \overline{\mathrm{b}}| & =|\overline{\mathrm{a}}||\overline{\mathrm{b}}| \sin \theta \\
& \therefore \quad \sin \theta & =\frac{|\overline{\mathrm{a}} \times \overline{\mathrm{b}}|}{|\overline{\mathrm{a}}||\overline{\mathrm{b}}|}=\frac{35}{\sqrt{27} \times 7}=\frac{5}{\sqrt{27}} \\
\therefore & \cos \theta=\sqrt{1-\frac{25}{27}}=\sqrt{\frac{2}{27}}
\end{array}
Now, $\begin{aligned} \bar{a} \cdot \bar{b} & =|\bar{a}||\bar{b}| \cos \theta \\ & =\sqrt{27} \times 7 \times \sqrt{\frac{2}{27}}=7 \sqrt{2}\end{aligned}

Let $\overline{\mathrm{a}}=C x \hat{\mathrm{i}}-6 \hat{\mathrm{j}}-3 \hat{\mathrm{k}}$ and
$\overline{\mathrm{b}}=x \hat{\mathrm{i}}+2 \hat{\mathrm{j}}+2 \mathrm{C} x \hat{\mathrm{k}}$<br/>Angle between $\overline{\mathrm{a}}$ and $\overline{\mathrm{b}}$ is obtuse.
$\begin{array}{ll}
\therefore & \overline{\mathrm{a}} \cdot \overline{\mathrm{~b}} \lt \cos 180^{\circ} \\
\therefore & \overline{\mathrm{a}} \cdot \overline{\mathrm{~b}} \lt 0 \\
\therefore & \mathrm{C} x^2-12-6 \mathrm{C} x \lt 0
\end{array}
$\begin{aligned} & \Rightarrow \mathrm{C} x^2-6 \mathrm{C} x-12 \lt 0 \\ & \Rightarrow \mathrm{C} \lt 0 \text { and } \mathrm{D} \lt 0 \\ & \Rightarrow \mathrm{C} \lt 0 \text { and } 36 \mathrm{C}^2+48 \mathrm{C} \lt 0 \\ & \Rightarrow \mathrm{C} \lt 0 \text { and } 3 \mathrm{C}^2+4 \mathrm{C} \lt 0 \\ & \Rightarrow \mathrm{C} \lt 0, \mathrm{C}(3 \mathrm{C}+4) \lt 0 \\ & \Rightarrow \mathrm{C} \lt 0,-\frac{4}{3} \lt \mathrm{C} \lt 0 \\ \therefore \quad \mathrm{C} & =\left(-\frac{4}{3}, 0\right)\end{aligned}

$\begin{aligned}
& \text { Given, } \overline{\mathrm{b}} \times \overline{\mathrm{c}}=\overline{\mathrm{b}} \times \overline{\mathrm{a}} \\
& \Rightarrow \overline{\mathrm{b}} \times(\overline{\mathrm{c}}-\overline{\mathrm{a}})=\overline{0}
\end{aligned}\Rightarrow \overline{\mathrm{b}}$ is parallel to $(\overline{\mathrm{c}}-\overline{\mathrm{a}})$.
$\begin{aligned} & \Rightarrow \overline{\mathrm{c}}-\overline{\mathrm{a}}=\lambda \overline{\mathrm{b}} \text { for some scalar } \lambda \\ & \Rightarrow \overline{\mathrm{c}}=\overline{\mathrm{a}}+\lambda \overline{\mathrm{b}}... (i)) \\ & \Rightarrow \overline{\mathrm{c}} \cdot \overline{\mathrm{a}}=\overline{\mathrm{a}} \cdot \overline{\mathrm{a}}+\lambda(\overline{\mathrm{b}} \cdot \overline{\mathrm{a}})\end{aligned}\Rightarrow 0=|\overline{\mathrm{a}}|^2+\lambda(\overline{\mathrm{b}} \cdot \overline{\mathrm{a}}), \quad \cdots[\because \overline{\mathrm{c}} \cdot \overline{\mathrm{a}}=0$ (given) $]\begin{aligned}
& \Rightarrow 0=6 \pm 4 \lambda \\
& \Rightarrow \lambda=-\frac{3}{2}
\end{aligned}$
Substitutifing the value of $\lambda$ in (i), we get
$\begin{aligned}
\bar{c} & =(\hat{i}+2 \hat{j}-\hat{k})-\frac{3}{2}(\hat{i}+\hat{j}-\hat{k}) \\
= & -\frac{1}{2}(\hat{i}-\hat{j}-\hat{k}) \\
\therefore \quad \bar{c} \cdot \bar{b} & =-\frac{1}{2}(\hat{i}-\hat{j}-\hat{k}) \cdot(\hat{i}+\hat{j}-\hat{k}) \\
& =-\frac{1}{2}(1-1+1)=-\frac{1}{2}
\end{aligned}$

Let $\theta$ be the angle between $\bar{a}$ and $\bar{b}$.

\begin{aligned}
& \text { Since } \overline{\mathrm{c}}=\lambda(\overline{\mathrm{a}} \times \overline{\mathrm{b}}) \\
& \Rightarrow \overline{\mathrm{c}} \perp \overline{\mathrm{a}}, \overline{\mathrm{c}} \perp \overline{\mathrm{b}} \\
& \Rightarrow \overline{\mathrm{c}} \cdot \overline{\mathrm{a}}=\overline{\mathrm{c}} \cdot \overline{\mathrm{b}}=0
\end{aligned}

Now,

\begin{aligned}
